1	import { useCallback, useRef, useState } from "react";
2	import type {
3	  DragEndEvent,
4	  DragMoveEvent,
5	  DragOverEvent,
6	  DragStartEvent,
7	} from "@dnd-kit/core";
8	import { moveItems, setOrder } from "@/api/notes-api";
9	import { logGroup } from "@/api/invoke";
10	import {
11	  setActiveNote,
12	  setLastSelectedFolder,
13	  setLastSelectedNote,
14	  setSelectedFolders,
15	  setSelectedNotes,
16	  useSelection,
17	} from "@/state/selection-store";
18	import { clearNote } from "@/state/editor-store";
19	import {
20	  refreshTree,
21	  selectFlatItems,
22	  selectOrderedIds,
23	  selectParentById,
24	  selectTreeData,
25	  setExpanded,
26	  setTree,
27	  useNotesStore,
28	} from "@/state/notes-store";
29	import type { DragData } from "@typenotes/shared/types";
30	import { isSystemFolder } from "@typenotes/shared/constants";
31	import { getNoteParentPath } from "@typenotes/shared/notes";
32	import { DROP_PREFIX } from "@/lib/notes/tree-dnd";
33	import {
34	  findNode,
35	  findParentAndIndex,
36	  getNodeById,
37	  removeNodes,
38	  insertNodes,
39	  parseDropTargetId,
40	  sortIdsByTreeOrder,
41	  isInDraggedSubtree,
42	  getTopLevelSelected,
43	  arraysEqual,
44	  buildFolderOrderMap,
45	  applyFolderOrder,
46	  buildNoteOrderMap,
47	  reorderList,
48	  flattenTree,
49	} from "@/lib/notes/tree-ops";
50	import type { TreeItem } from "@/lib/notes/types";
51	
52	export function useDragDrop() {
53	  const tree = useNotesStore((state) => state.tree);
54	  const treeData = useNotesStore(selectTreeData);
55	  const flatItems = useNotesStore(selectFlatItems);
56	  const orderedIds = useNotesStore(selectOrderedIds);
57	  const expanded = useNotesStore((state) => state.expanded);
58	  const parentById = useNotesStore(selectParentById);
59	  const selectedFolders = useSelection((state) => state.selectedFolders);
60	  const selectedNotes = useSelection((state) => state.selectedNotes);
61	  const activeNote = useSelection((state) => state.activeNote);
62	  const [activeId, setActiveId] = useState<string | null>(null);
63	  const [edgeSnap, setEdgeSnap] = useState<{
64	    id: string;
65	    position: "before" | "after";
66	  } | null>(null);
67	  const activeDrag = useRef<DragData | null>(null);
68	  const dragStartPoint = useRef<{ x: number; y: number } | null>(null);
69	  const expandTimeoutRef = useRef<number | null>(null);
70	  const expandTargetRef = useRef<string | null>(null);
71	
72	  const handleDragStart = useCallback(
73	    ({ active, activatorEvent }: DragStartEvent) => {
74	      const data = active.data.current as DragData | undefined;
75	      if (!data) return;
76	      activeDrag.current = data;
77	      logGroup("drag start", {
78	        type: data.type,
79	        path: "path" in data ? data.path : undefined,
80	        id: active.id.toString(),
81	      });
82	      if (data.type === "folder") {
83	        const point =
84	          activatorEvent instanceof globalThis.MouseEvent
85	            ? { x: activatorEvent.clientX, y: activatorEvent.clientY }
86	            : null;
87	        dragStartPoint.current = point;
88	        setActiveId(active.id.toString());
89	        setSelectedFolders((prev) =>
90	          prev.has(data.path) ? prev : new Set([data.path])
91	        );
92	        setLastSelectedFolder(data.path);
93	        document.body.style.setProperty("cursor", "grabbing");
94	      }
95	      if (data.type === "note") {
96	        setSelectedNotes((prev) =>
97	          prev.has(data.path) ? prev : new Set([data.path])
98	        );
99	        setLastSelectedNote(data.path);
100	        setActiveNote(data.path);
101	      }
102	    },
103	    [setSelectedFolders, setLastSelectedFolder, setSelectedNotes, setLastSelectedNote, setActiveNote]
104	  );
105	
106	  const handleDragMove = useCallback(
107	    (event: DragMoveEvent) => {
108	      if (activeDrag.current?.type !== "folder") return;
109	      const { active, over } = event;
110	      if (!active || !over) {
111	        setEdgeSnap(null);
112	        if (expandTimeoutRef.current) {
113	          window.clearTimeout(expandTimeoutRef.current);
114	          expandTimeoutRef.current = null;
115	        }
116	        expandTargetRef.current = null;
117	        return;
118	      }
119	      const dropTarget = parseDropTargetId(over.id);
120	      if (!dropTarget || dropTarget.type !== "item" || dropTarget.position !== "inside") {
121	        setEdgeSnap(null);
122	        if (expandTimeoutRef.current) {
123	          window.clearTimeout(expandTimeoutRef.current);
124	          expandTimeoutRef.current = null;
125	        }
126	        expandTargetRef.current = null;
127	        return;
128	      }
129	
130	      // Spring-load: hovering a collapsed folder for 500ms auto-expands it, so
131	      // you can drill into a nested folder mid-drag without dropping first.
132	      const overNode = getNodeById(treeData, dropTarget.itemId);
133	      const hasChildren = Boolean(overNode?.children && overNode.children.length > 0);
134	      const isCollapsed = hasChildren && !expanded.has(dropTarget.itemId);
135	      if (isCollapsed) {
136	        if (expandTargetRef.current !== dropTarget.itemId) {
137	          if (expandTimeoutRef.current) window.clearTimeout(expandTimeoutRef.current);
138	          expandTargetRef.current = dropTarget.itemId;
139	          expandTimeoutRef.current = window.setTimeout(() => {
140	            setExpanded((prev) => {
141	              const next = new Set(prev);
142	              next.add(dropTarget.itemId);
143	              return next;
144	            });
145	          }, 500);
146	        }
147	      } else if (expandTargetRef.current) {
148	        if (expandTimeoutRef.current) {
149	          window.clearTimeout(expandTimeoutRef.current);
150	          expandTimeoutRef.current = null;
151	        }
152	        expandTargetRef.current = null;
153	      }
154	
155	      const overRect = over.rect;
156	      if (!overRect) {
157	        setEdgeSnap(null);
158	        return;
159	      }
160	
161	      // Prefer the live pointer position (drag-start point + dnd-kit delta);
162	      // fall back to the dragged row's center when the drag wasn't mouse-driven.
163	      let pointerY: number | null = null;
164	      if (dragStartPoint.current && typeof event.delta?.y === "number") {
165	        pointerY = dragStartPoint.current.y + event.delta.y;
166	      } else {
167	        const activeRect = active.rect.current?.translated ?? active.rect.current?.initial;
168	        if (activeRect) pointerY = activeRect.top + activeRect.height / 2;
169	      }
170	
171	      if (pointerY === null) {
172	        setEdgeSnap(null);
173	        return;
174	      }
175	
176	      // Top/bottom edge zones snap to before/after the row (reorder); the middle
177	      // means "drop inside". The zone is ~35% of row height, capped at 14px.
178	      const height = overRect.bottom - overRect.top;
179	      const threshold = Math.min(14, height * 0.35);
180	
181	      if (pointerY < overRect.top + threshold) {
182	        setEdgeSnap({ id: dropTarget.itemId, position: "before" });
183	        return;
184	      }
185	      if (pointerY > overRect.bottom - threshold) {
186	        if (hasChildren) {
187	          // "After" is ambiguous for a folder with children (after the row, or
188	          // after its whole subtree?), so fall back to dropping inside it.
189	          setEdgeSnap(null);
190	          return;
191	        }
192	        setEdgeSnap({ id: dropTarget.itemId, position: "after" });
193	        return;
194	      }
195	      setEdgeSnap(null);
196	    },
197	    [expanded, setExpanded, treeData]
198	  );
199	
200	  const handleDragOver = useCallback(
201	    (event: DragOverEvent) => {
202	      if (activeDrag.current?.type !== "folder") return;
203	      if (!event.over) setEdgeSnap(null);
204	    },
205	    []
206	  );
207	
208	  // Folder drops: reparent / reorder the dragged folder subtree, then persist
209	  // the moves + per-parent folder order and refresh if any parent changed.
210	  const handleFolderDragEnd = useCallback(
211	    async (event: DragEndEvent) => {
212	      const { over } = event;
213	
214	      setActiveId(null);
215	      setEdgeSnap(null);
216	      document.body.style.setProperty("cursor", "");
217	      dragStartPoint.current = null;
218	      activeDrag.current = null;
219	      if (expandTimeoutRef.current) {
220	        window.clearTimeout(expandTimeoutRef.current);
221	        expandTimeoutRef.current = null;
222	      }
223	      expandTargetRef.current = null;
224	
225	      if (!over) return;
226	
227	      const resolvedId =
228	        edgeSnap ? `${DROP_PREFIX}:${edgeSnap.id}:${edgeSnap.position}` : over.id;
229	      const dropTarget = parseDropTargetId(resolvedId);
230	      if (!dropTarget) {
231	        logGroup("drop ignored", { reason: "invalid target", overId: over.id });
232	        return;
233	      }
234	
235	      const selectedIdsList = Array.from(selectedFolders);
236	      const draggingIds = getTopLevelSelected(selectedIdsList, parentById);
237	      if (draggingIds.length === 0) {
238	        logGroup("drop ignored", { reason: "no dragging ids" });
239	        return;
240	      }
241	
242	      if (dropTarget.type === "item" && draggingIds.includes(dropTarget.itemId)) {
243	        logGroup("drop ignored", { reason: "target is dragged item", target: dropTarget });
244	        return;
245	      }
246	
247	      if (
248	        dropTarget.type === "item" &&
249	        isInDraggedSubtree(treeData, draggingIds, dropTarget.itemId)
250	      ) {
251	        logGroup("drop ignored", {
252	          reason: "target inside dragged subtree",
253	          target: dropTarget,
254	        });
255	        return;
256	      }
257	
258	      const orderedDraggingIds = sortIdsByTreeOrder(draggingIds, orderedIds);
259	      if (orderedDraggingIds.some(isSystemFolder)) {
260	        logGroup("drop ignored", { reason: "system folder drag blocked" });
261	        return;
262	      }
263	      // Optimistic local rebuild: pull the dragged subtrees out, then splice
264	      // them back in at the resolved target before persisting to the backend.
265	      const { tree: prunedTree, removed } = removeNodes(treeData, orderedDraggingIds);
266	      const removedMap = new Map(removed.map((node) => [node.id, node]));
267	      const nodesToInsert = orderedDraggingIds
268	        .map((id) => removedMap.get(id))
269	        .filter(Boolean) as TreeItem[];
270	
271	      if (nodesToInsert.length === 0) return;
272	
273	      let targetParentId: string | null = null;
274	      let targetIndex = 0;
275	
276	      if (dropTarget.type === "root") {
277	        targetParentId = null;
278	        targetIndex = prunedTree.length;
279	      } else if (dropTarget.position === "inside") {
280	        targetParentId = dropTarget.itemId;
281	        const parentNode = getNodeById(prunedTree, dropTarget.itemId);
282	        targetIndex = parentNode?.children?.length ?? 0;
283	      } else {
284	        const position = findParentAndIndex(prunedTree, dropTarget.itemId);
285	        if (!position) return;
286	        targetParentId = position.parentId;
287	        targetIndex = position.index + (dropTarget.position === "after" ? 1 : 0);
288	      }
289	
290	      const nextTree = insertNodes(prunedTree, targetParentId, targetIndex, nodesToInsert);
291	      logGroup("folder drag drop", {
292	        dropTarget,
293	        draggingIds: orderedDraggingIds,
294	        targetParentId: targetParentId ?? "",
295	        targetIndex,
296	        selectedFolders: Array.from(selectedFolders),
297	      });
298	
299	      const oldParentById: Record<string, string | null> = {};
300	      flatItems.forEach((item) => {
301	        oldParentById[item.id] = item.parentId;
302	      });
303	      const newParentById: Record<string, string | null> = {};
304	      flattenTree(nextTree).forEach((item) => {
305	        newParentById[item.id] = item.parentId;
306	      });
307	
308	      // Only folders whose parent actually changed need a filesystem move;
309	      // pure reordering within a parent is persisted via setOrder below.
310	      for (const id of orderedDraggingIds) {
311	        const oldParent = oldParentById[id] ?? null;
312	        const newParent = newParentById[id] ?? null;
313	        if (oldParent !== newParent) {
314	          await moveItems([id], newParent ?? "");
315	        }
316	      }
317	
318	      const noteOrderMap: Record<string, string[]> = {};
319	      buildNoteOrderMap(tree, noteOrderMap);
320	
321	      const currentOrderMap: Record<string, string[]> = {};
322	      const nextOrderMap: Record<string, string[]> = {};
323	      buildFolderOrderMap(treeData, null, currentOrderMap);
324	      buildFolderOrderMap(nextTree, null, nextOrderMap);
325	
326	      // Diff the per-parent child order so we only rewrite the .notes-order.json
327	      // of parents whose sequence actually changed, not every folder in the tree.
328	      const changedParents = Object.keys(nextOrderMap).filter(
329	        (parent) => !arraysEqual(nextOrderMap[parent], currentOrderMap[parent])
330	      );
331	
332	      logGroup("folder order delta", {
333	        changedParents,
334	        totalParents: Object.keys(nextOrderMap).length,
335	      });
336	
337	      for (const parentPath of changedParents) {
338	        await setOrder({
339	          parent: parentPath,
340	          folderOrder: nextOrderMap[parentPath],
341	          noteOrder: noteOrderMap[parentPath] || [],
342	        });
343	      }
344	
345	      if (changedParents.length > 0 && tree) {
346	        setTree(applyFolderOrder(tree, nextOrderMap));
347	      }
348	
349	      if (orderedDraggingIds.some((id) => oldParentById[id] !== newParentById[id])) {
350	        await refreshTree();
351	      }
352	    },
353	    [edgeSnap, flatItems, orderedIds, parentById, refreshTree, selectedFolders, setTree, tree, treeData]
354	  );
355	
356	  // Note drops: move the dragged note(s) to a folder / another note's parent,
357	  // or reorder within the current parent.
358	  const handleNoteDragEnd = useCallback(
359	    async (event: DragEndEvent) => {
360	      const { active, over } = event;
361	      const data = active.data.current as DragData | undefined;
362	      const overData = over?.data.current as DragData | undefined;
363	      if (!data || data.type !== "note") return;
364	
365	      activeDrag.current = null;
366	      if (!over || !overData) {
367	        logGroup("note drop ignored", { reason: "missing target" });
368	        return;
369	      }
370	      const selectedList = selectedNotes.has(data.path)
371	        ? Array.from(selectedNotes)
372	        : [data.path];
373	      const sourceParentPath = getNoteParentPath(data.path);
374	      if (overData.type === "folder") {
375	        logGroup("note move to folder", {
376	          notes: selectedList,
377	          destination: overData.path,
378	        });
379	        await moveItems(selectedList, overData.path);
380	        if (selectedList.includes(activeNote || "")) {
381	          setActiveNote(null);
382	          clearNote();
383	        }
384	        setSelectedNotes(new Set());
385	        setLastSelectedNote("");
386	        await refreshTree();
387	        return;
388	      }
389	      if (overData.type === "note") {
390	        const destinationParentPath = getNoteParentPath(overData.path);
391	        if (destinationParentPath !== sourceParentPath) {
392	          logGroup("note move to note parent", {
393	            notes: selectedList,
394	            destination: destinationParentPath,
395	            over: overData.path,
396	          });
397	          await moveItems(selectedList, destinationParentPath);
398	          if (selectedList.includes(activeNote || "")) {
399	            setActiveNote(null);
400	            clearNote();
401	          }
402	          setSelectedNotes(new Set());
403	          setLastSelectedNote("");
404	          await refreshTree();
405	          return;
406	        }
407	
408	        const parentNode = findNode(tree, destinationParentPath);
409	        if (!parentNode) {
410	          logGroup("note drop ignored", {
411	            reason: "missing destination parent",
412	            destinationParentPath,
413	          });
414	          return;
